-- Haradon creatures, spawns, vendors and quest givers
-- Generated by NetCoreClient/tools/M425Patch from the 425 tables. Do not edit; re-run tools/build-m425.sh.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `m425_creature_stats` (
  `entry` mediumint unsigned NOT NULL,
  `health` int unsigned NOT NULL,
  `mana` int unsigned NOT NULL,
  `damage` float NOT NULL,
  `armor` int unsigned NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COMMENT='m425: 425 creature stats the multipliers are derived from';
DELETE FROM `m425_creature_stats` WHERE `entry` BETWEEN 900000 AND 999999;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 900000 AND 999999;
DELETE FROM `creature` WHERE `guid` BETWEEN 9000000 AND 9999999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9000000 AND 9999999;
DELETE FROM `creature_display_info_addon` WHERE `display_id` BETWEEN 50000 AND 99999;
DELETE FROM `npc_vendor` WHERE `entry` BETWEEN 900000 AND 999999;
DELETE FROM `creature_questrelation` WHERE `id` BETWEEN 900000 AND 999999;
DELETE FROM `creature_involvedrelation` WHERE `id` BETWEEN 900000 AND 999999;

UPDATE `creature_template` SET `npc_flags` = `npc_flags` | 2 WHERE `entry` BETWEEN 900000 AND 999999 AND `entry` IN
    (SELECT `id` FROM `creature_questrelation` UNION SELECT `id` FROM `creature_involvedrelation`);
UPDATE `creature_template` t JOIN `m425_creature_stats` m ON m.`entry` = t.`entry` JOIN `creature_classlevelstats` s ON s.`class` = t.`unit_class` AND s.`level` = (t.`level_min` + t.`level_max`) DIV 2
SET t.`health_multiplier` = GREATEST(0.01, m.`health` / GREATEST(1, s.`health`)),
    t.`mana_multiplier` = IF(s.`mana` > 0, m.`mana` / s.`mana`, 1),
    t.`damage_multiplier` = GREATEST(0.01, m.`damage` / GREATEST(0.1, s.`melee_damage`)),
    t.`armor_multiplier` = IF(s.`armor` > 0, m.`armor` / s.`armor`, 1)
WHERE t.`entry` BETWEEN 900000 AND 999999;
